{
  "id": "muse",
  "name": "muse",
  "version": "1.0.1",
  "description": "Component specification plugin. Turns UI/design intent into unambiguous, testable component specs — props, variants, per-state behavior, and accessibility criteria as testable propositions, gated before planning. Audits the spec, not the implementation — see ranger's accessibility hazard taxonomy for code-level scanning.",
  "author": {
    "name": "Gabriel Castro",
    "email": "gabe@techworx.dev"
  },
  "skills": "./skills/",
  "agents": [
    "./agents/auditor.md",
    "./agents/drafter.md",
    "./agents/exit-gate.md"
  ],
  "consumes": [
    "requirement@1"
  ],
  "produces": [
    "spec@1",
    "verdict@1"
  ]
}

{
  "id": "navigator",
  "name": "navigator",
  "version": "2.3.2",
  "description": "Planning plugin. Decomposes specs into sequenced, bite-sized implementation plans with an implementation approach, exact code as a baseline, and the tests proving each criterion — no write-test-first mandate. Tasks are sized to compilation boundaries, not a clock-time estimate. No TBDs. A developer with zero domain context can execute the plan mechanically.",
  "author": {
    "name": "Gabriel Castro",
    "email": "gabe@techworx.dev"
  },
  "skills": "./skills/",
  "agents": [
    "./agents/challenger.md",
    "./agents/estimator.md",
    "./agents/planner.md"
  ],
  "consumes": [
    "spec@1"
  ],
  "produces": [
    "plan@1"
  ]
}

{
  "id": "sentinel",
  "name": "sentinel",
  "version": "2.1.2",
  "description": "Cross-cutting verification gate. Confirms any stage artifact meets its criteria before the next stage begins. Implements the sentinel protocol: recon \u2192 verify \u2192 exit-gate with retry-with-feedback.",
  "author": {
    "name": "Gabriel Castro",
    "email": "gabe@techworx.dev"
  },
  "skills": "./skills/",
  "agents": [
